def solve(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(x for row in inp for x in row)
    bg=cnt.most_common(1)[0][0]
    col=[k for k in cnt if k not in (0,bg)][0]
    colored=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==col]
    r0=min(r for r,c in colored); c0=min(c for r,c in colored)
    S=[(r-r0,c-c0) for r,c in colored]
    zeros={(r,c) for r in range(H) for c in range(W) if inp[r][c]==0}
    out=[row[:] for row in inp]
    for dr in range(H):
        for dc in range(W):
            if all(0<=r+dr<H and 0<=c+dc<W and (r+dr,c+dc) in zeros for r,c in S):
                for r,c in S: out[r+dr][c+dc]=col
    return out
